UPDATE quiz_questions SET question_ru = 'Исполнением какой роли особенно прославился Аброр Хидоятов?', options_ru = '["Фархада", "Отелло", "Муканны", "Гафура"]'::jsonb, explanation_ru = 'В учебнике «История театра» академик Камиль Яшен писал, что Аброр Хидоятов уже несколько лет играет роль Отелло с бесподобным мастерством — это было его самое знаменитое исполнение.' WHERE id = 2601;
UPDATE quiz_questions SET question_ru = 'Какую роль исполнил Аброр Хидоятов в спектакле «Алишер Навои», премьера которого прошла 1 апреля 1945 года?', options_ru = '["Хусейна Байкары", "Мадждиддина", "Алишера Навои", "Мансура"]'::jsonb, explanation_ru = 'В этом спектакле, поставленном Манноном Уйгуром, роль Алишера Навои играл Аброр Хидоятов, а роль Гули — Сора Эшонтураева.' WHERE id = 2602;
UPDATE quiz_questions SET question_ru = 'Каков самый знаменитый труд Абуль Муина ан-Насафи?', options_ru = '["«Бабурнаме»", "«Табсират аль-адилля»", "«Аль-Канун фит-тибб»", "«Дивану лугат ат-турк»"]'::jsonb, explanation_ru = 'Самый знаменитый труд учёного — «Табсират аль-адилля», в нём вопросы исламского вероучения освещены по пути Абу Мансура Матуриди.' WHERE id = 2603;
UPDATE quiz_questions SET question_ru = 'В каком городе родился Абуль Муин ан-Насафи?', options_ru = '["Самарканд", "Бухара", "Насаф (нынешний Карши)", "Хива"]'::jsonb, explanation_ru = 'Учёный родился в 1027 году в городе Насаф. Этот древний город располагался на месте нынешнего города Карши.' WHERE id = 2604;
UPDATE quiz_questions SET question_ru = 'В каком городе родился Аскад Мухтар?', options_ru = '["Ташкент", "Фергана", "Самарканд", "Андижан"]'::jsonb, explanation_ru = 'Аскад Мухтар родился 23 декабря 1920 года в городе Фергане, в семье железнодорожного рабочего.' WHERE id = 2605;
UPDATE quiz_questions SET question_ru = 'Какой из перечисленных романов принадлежит перу Аскада Мухтара?', options_ru = '["«Минувшие дни»", "«Чинара»", "«Мираж»", "«Ночь и день»"]'::jsonb, explanation_ru = '«Чинара» — роман Аскада Мухтара, изданный в 1973 году. Он написал также романы «Сёстры» (1955), «Рождение» (1963) и «Время в моей судьбе» (1964).' WHERE id = 2606;
UPDATE quiz_questions SET question_ru = 'В каких городах жил и творил Атаи?', options_ru = '["Самарканд, Бухара и Балх", "Хива, Коканд и Маргилан", "Багдад, Дамаск и Каир", "Дели, Лахор и Кабул"]'::jsonb, explanation_ru = 'Атаи жил в городах Самарканд, Бухара и Балх и основательно изучил тюркскую, персидскую и арабскую словесность.' WHERE id = 2607;
UPDATE quiz_questions SET question_ru = 'Сколько газелей собрано в рукописи дивана Атаи?', options_ru = '["100 газелей", "260 газелей", "500 газелей", "Более 1000 газелей"]'::jsonb, explanation_ru = 'В рукописи дивана Атаи, переписанной примерно в XVI веке, собрано 260 газелей; она хранится в Санкт-Петербурге.' WHERE id = 2608;
UPDATE quiz_questions SET question_ru = 'Где Батыр Закиров впервые исполнил «Арабское танго»?', options_ru = '["В театре Навои в Ташкенте", "На международном фестивале молодёжи и студентов в Москве в 1957 году", "В концертном зале в Париже", "На празднике искусства в Самарканде"]'::jsonb, explanation_ru = 'Как пишет УзА в статье «Батыр Закиров и музыка Востока», он впервые исполнил «Арабское танго» на международном фестивале молодёжи и студентов, прошедшем в 1957 году в Москве.' WHERE id = 2609;
