UPDATE quiz_questions SET question_ru = 'Какой знаменитый учёный был старшим братом Байсункара Мирзы?', options_ru = '["Мухаммад Джуки Мирза", "Хусейн Байкара", "Мирзо Улугбек", "Захириддин Мухаммад Бабур"]'::jsonb, explanation_ru = 'Старшим братом Байсункара Мирзы был знаменитый учёный Мирзо Улугбек (Мухаммад Тарагай), а младшим — Мухаммад Джуки Мирза.' WHERE id = 2612;
