UPDATE quiz_questions SET question_ru = 'Каков знаменитый труд Хакима ат-Термизи, положивший начало учению о святости?', options_ru = '["«Хатм уль-авлия»", "«Бабурнаме»", "«Дивану лугат ат-турк»", "«Аль-Канун фит-тибб»"]'::jsonb, explanation_ru = '«Хатм уль-авлия» состоит из предисловия и 29 глав; в нём положено начало учению о святости. Остальные труды принадлежат перу других учёных.' WHERE id = 2624;
UPDATE quiz_questions SET question_ru = 'Как называется течение суфизма, возникшее благодаря ученикам и последователям Хакима ат-Термизи?', options_ru = '["Накшбандия", "Яссавия", "Хакимия", "Кубравия"]'::jsonb, explanation_ru = 'Благодаря ученикам и последователям учёного возникло течение суфизма, названное «аль-хакимия ват-термизия». А накшбандия, яссавия и кубравия связаны с именами других учёных.' WHERE id = 2625;
UPDATE quiz_questions SET question_ru = 'Поэтом какого народа был Кунходжа?', options_ru = '["Каракалпакского", "Казахского", "Туркменского", "Таджикского"]'::jsonb, explanation_ru = 'Верный ответ — каракалпакского. Кунходжа, сын Ибрахима (1799–1880), был каракалпакским поэтом. Источник: Национальная энциклопедия Узбекистана, статья «Кунходжа».' WHERE id = 2629;
UPDATE quiz_questions SET question_ru = 'Какое из перечисленных произведений принадлежит перу Кунходжи?', options_ru = '["«Белый камыш»", "«Бабурнаме»", "«Хамса»", "«Минувшие дни»"]'::jsonb, explanation_ru = 'Верный ответ — «Белый камыш». В этом стихотворении, как и в стихах «Жнецы» и «Чабаны», отразились жизнь каракалпаков и тяготы их быта. Источник: Национальная энциклопедия Узбекистана, статья «Кунходжа».' WHERE id = 2630;
UPDATE quiz_questions SET question_ru = 'Где родилась Лютфиханум Сарымсакова?', options_ru = '["В городе Ташкенте", "В Риштанском районе Ферганской области", "В городе Бухаре", "В городе Хиве"]'::jsonb, explanation_ru = 'Лютфиханум Сарымсакова появилась на свет в 1896 году в Риштанском районе Ферганской области.' WHERE id = 2631;
UPDATE quiz_questions SET question_ru = 'Какую роль исполнила Лютфиханум Сарымсакова в фильме «Об этом говорит вся махалля»?', options_ru = '["Ойсары", "Сестрицы Фатимы", "Мехринисо", "Ясуман"]'::jsonb, explanation_ru = 'В этом фильме она сыграла роль Мехринисо; а сестрица Фатима — её образ в фильме «Ты не сирота».' WHERE id = 2632;
UPDATE quiz_questions SET question_ru = 'Как отозвался Алишер Навои о Лутфи?', options_ru = '["«Малик уль-калам» своего времени — царь слова", "Завоеватель мира", "Великий врачеватель", "Искусный зодчий"]'::jsonb, explanation_ru = 'Навои возвеличил Лутфи как «малик уль-калама» своего времени — поэта, которому нет равных ни в персидском, ни в тюркском; об этом сказано в тазкире «Маджолис ун-нафоис».' WHERE id = 2633;
UPDATE quiz_questions SET question_ru = 'Сколько лет прожил Лутфи?', options_ru = '["45 лет", "63 года", "99 лет", "120 лет"]'::jsonb, explanation_ru = 'Лутфи родился в 1366 году и скончался в 1465 году — то есть прожил 99 лет и слагал стихи даже перевалив за девяносто.' WHERE id = 2634;
UPDATE quiz_questions SET question_ru = 'Как называется знаменитая лирическая повесть Миртемира, написанная в 1956–1957 годах?', options_ru = '["«Победа»", "«Портрет»", "«Набат»", "«Дилькушо»"]'::jsonb, explanation_ru = '«Портрет» — лирическая повесть Миртемира, написанная в 1956–1957 годах; она сильно повлияла на развитие жанра лирической поэмы в узбекской поэзии.' WHERE id = 2635;
UPDATE quiz_questions SET question_ru = 'Какой киргизский народный эпос перевёл Миртемир на узбекский язык?', options_ru = '["«Алпамыш»", "«Гороглы»", "«Манас»", "«Шахнаме»"]'::jsonb, explanation_ru = 'Миртемир перевёл на узбекский язык киргизский народный эпос «Манас». Он переложил также произведения Пушкина, Некрасова, Абая, Махтумкули и Бердаха.' WHERE id = 2636;
